WITH subscriptions_by_customer AS (SELECT customer_id, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) cancelled_count FROM subscriptions WHERE plan = 'enterprise' GROUP BY customer_id) SELECT c.id, c.name, c.email, sbc.cancelled_count FROM customers c INNER JOIN subscriptions_by_customer sbc ON c.id = sbc.customer_id WHERE sbc.cancelled_count >= 73 ORDER BY c.id DESC, name DESC LIMIT 5
